import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, delayRender, continueRender } from '../remotionShim';
// ---------------------------------------------------------------------------
// BRAND FONT LOADING (Module Level)
// ---------------------------------------------------------------------------
if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const font = new FontFace(family, `url('${url}') format('truetype')`);
    font.load()
      .then(() => {
        document.fonts.add(font);
        continueRender(handle);
      })
      .catch((err) => {
        console.log(`Error loading ${family}`, err);
        continueRender(handle);
      });
  };
  loadCustomFont("TuskerGrotesk", "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/4b954368156447d584b4e82c28890f47.ttf");
}

// ---------------------------------------------------------------------------
// FILTER IDS
// ---------------------------------------------------------------------------
const grainFilterId = "macromoney-grain";
const glowFilterId = "macromoney-glow";

// ---------------------------------------------------------------------------
// SCHEMA
// ---------------------------------------------------------------------------


export type MacromoneyTitleProps = Record<string, any>;

// ---------------------------------------------------------------------------
// HELPER FUNCTIONS FOR GENERATIVE GRAPHICS
// ---------------------------------------------------------------------------
const generateJaggedLine = (startX: number, startY: number, segments: number, xStep: number, yRange: number, seed: number) => {
  let d = `M ${startX} ${startY}`;
  let curX = startX;
  let curY = startY;
  for (let i = 1; i <= segments; i++) {
    curX += xStep;
    // Deterministic random walk using sine
    const offset = Math.sin(seed * i * 12.345) * yRange;
    curY += offset;
    d += ` L ${curX} ${curY}`;
  }
  return d;
};

// ---------------------------------------------------------------------------
// MAIN COMPONENT
// ---------------------------------------------------------------------------
const MacromoneyTitle: React.FC<MacromoneyTitleProps> = ({
  title = "MACROMONEY",
  titleFontFamily = "TuskerGrotesk",
  backgroundColor = "#1D191B",
  transparentBackground = false,
  durationInSeconds = 6,
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Parser Safety
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Colors
  const cIvory = "#F2E9D8";
  const cRed = "#E21F26";
  const cChartreuse = "#C1D92B";
  const cGray = "#555555";
  const cLightGray = "#888888";

  // ---------------------------------------------------------------------------
  // KEYFRAME DERIVATION
  // ---------------------------------------------------------------------------
  const totalFrames = durationInSeconds * fps;
  const holdDriftEnd = 0.133 * totalFrames;
  const pullbackEnd = 0.767 * totalFrames;
  const titleFadeStart = 0.722 * totalFrames;
  const titleFadeEnd = 0.889 * totalFrames;

  // ---------------------------------------------------------------------------
  // CAMERA ANIMATION LOGIC
  // ---------------------------------------------------------------------------
  // The camera starts heavily zoomed in on a specific dense data node, then pulls back.
  const focusStartX = width * 0.365; // ~700
  const focusStartY = height * 0.370; // ~400
  
  // Subtle drift during the initial hold phase
  const driftPx = interpolate(frame, [0, holdDriftEnd], [focusStartX, focusStartX - 10], { extrapolateRight: "clamp" });
  const driftPy = interpolate(frame, [0, holdDriftEnd], [focusStartY, focusStartY + 5], { extrapolateRight: "clamp" });

  // Main pullback progress
  const pullProgress = interpolate(frame, [holdDriftEnd, pullbackEnd], [0, 1], {
    easing: Easing.bezier(0.6, 0.05, 0.4, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });

  // Perceptually linear zoom using log space
  const curScale = Math.exp(interpolate(pullProgress, [0, 1], [Math.log(20), 0]));
  const curPx = interpolate(pullProgress, [0, 1], [driftPx, width / 2]);
  const curPy = interpolate(pullProgress, [0, 1], [driftPy, height / 2]);

  // Viewbox coordinates driving the camera directly
  const vw = width / curScale;
  const vh = height / curScale;
  const vx = curPx - vw / 2;
  const vy = curPy - vh / 2;

  // ---------------------------------------------------------------------------
  // LIVE PATH TRUNCATION (Rule 7: Growing a path with a tip rider)
  // ---------------------------------------------------------------------------
  // We grow a quadratic bezier curve to simulate live updating market data
  const p0 = { x: 300, y: 700 };
  const p1 = { x: 500, y: 1000 };
  const p2 = { x: 900, y: 800 };
  
  const growT = interpolate(frame, [0, totalFrames], [0.2, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });
  
  // De Casteljau interpolation
  const L = (a: number, b: number, t: number) => a + (b - a) * t;
  const q0x = L(p0.x, p1.x, growT);
  const q0y = L(p0.y, p1.y, growT);
  const q1x = L(p1.x, p2.x, growT);
  const q1y = L(p1.y, p2.y, growT);
  const tipX = L(q0x, q1x, growT);
  const tipY = L(q0y, q1y, growT);
  
  const livePathD = `M ${p0.x} ${p0.y} Q ${q0x} ${q0y}, ${tipX} ${tipY}`;

  // ---------------------------------------------------------------------------
  // STATIC BACKGROUND GENERATION
  // ---------------------------------------------------------------------------
  const gridLines = useMemo(() => {
    const lines = [];
    for (let i = 0; i <= height; i += 60) {
      lines.push(<line key={`h-${i}`} x1={0} x2={width} y1={i} y2={i} stroke={cGray} strokeWidth={0.5} opacity={0.2} />);
    }
    for (let i = 0; i <= width; i += 60) {
      lines.push(<line key={`v-${i}`} x1={i} x2={i} y1={0} y2={height} stroke={cGray} strokeWidth={0.5} opacity={0.2} />);
    }
    return lines;
  }, [width, height, cGray]);

  const jaggedLines = useMemo(() => {
    return (
      <g>
        <path d={generateJaggedLine(0, 500, 40, 50, 40, 1)} fill="none" stroke={cLightGray} strokeWidth={1} opacity={0.4} />
        <path d={generateJaggedLine(200, 900, 30, 60, 60, 2)} fill="none" stroke={cIvory} strokeWidth={0.5} opacity={0.3} />
        <path d={generateJaggedLine(1000, 200, 20, 45, 20, 3)} fill="none" stroke={cRed} strokeWidth={1} opacity={0.5} />
      </g>
    );
  }, [cLightGray, cIvory, cRed]);

  // ---------------------------------------------------------------------------
  // TITLE ANIMATION
  // ---------------------------------------------------------------------------
  const titleOpacity = interpolate(frame, [titleFadeStart, titleFadeEnd], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const titleBlur = interpolate(frame, [titleFadeStart, titleFadeEnd], [10, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", fontFamily: titleFontFamily }}>
      
      {/* CAMERA VIEW (MACRO SYSTEM VISUALIZATION) */}
      <svg
        viewBox={`${vx} ${vy} ${vw} ${vh}`}
        width="100%"
        height="100%"
        style={{ position: "absolute", overflow: "visible" }}
      >
        <defs>
          <filter id={glowFilterId}>
            <feGaussianBlur stdDeviation="2" />
          </filter>
        </defs>

        {/* Base Grid */}
        {gridLines}

        {/* Major Sweeping Curves */}
        {/* Curve 1 (Red) - Crosses the focal node */}
        <path d="M -100 900 C 300 900, 500 400, 700 400 S 1100 200, 2000 300" fill="none" stroke={cRed} strokeWidth={2} strokeLinecap="round" opacity={0.8} />
        
        {/* Curve 2 (Chartreuse) - Crosses the focal node */}
        <path d="M 200 100 Q 450 250, 700 400 T 1700 900" fill="none" stroke={cChartreuse} strokeWidth={1.5} strokeLinecap="round" opacity={0.7} />
        
        {/* Curve 3 (Ivory Dashed) - Crosses the focal node */}
        <path d="M 0 600 Q 350 500, 700 400 T 2000 100" fill="none" stroke={cIvory} strokeWidth={1} strokeLinecap="round" strokeDasharray="4 6" opacity={0.6} />

        {/* Jagged Trend Lines */}
        {jaggedLines}

        {/* Focal Node Nexus (x: 700, y: 400) - This is what we see at t=0 */}
        <g>
          <line x1={680} x2={720} y1={400} y2={400} stroke={cIvory} strokeWidth={1} />
          <line x1={700} x2={700} y1={380} y2={420} stroke={cIvory} strokeWidth={1} />
          <circle cx={700} cy={400} r={3} fill={cRed} />
          <circle cx={700} cy={400} r={8} fill="none" stroke={cRed} strokeWidth={0.5} opacity={0.5} />
          <text x={708} y={395} fill={cIvory} fontSize={8} letterSpacing={0.5}>0.382</text>
          
          {/* Tiny execution dots nearby */}
          <circle cx={690} cy={390} r={1} fill={cChartreuse} />
          <circle cx={715} cy={410} r={1} fill={cIvory} />
        </g>

        {/* Live Updating Projection Curve (Rule 7 Implementation) */}
        <g>
          <path d={livePathD} fill="none" stroke={cIvory} strokeWidth={1.5} strokeLinecap="round" opacity={0.8} />
          {/* Tip Rider: Glowing Dot */}
          <circle cx={tipX} cy={tipY} r={2.5} fill={cIvory} />
          <circle cx={tipX} cy={tipY} r={8} fill={cIvory} opacity={0.2} filter={`url(#${glowFilterId})`} />
          <text x={tipX + 8} y={tipY - 5} fill={cIvory} fontSize={6} letterSpacing={0.5} opacity={0.8}>PROJ</text>
        </g>

        {/* Secondary Details & Labels spread across the macro view */}
        <g fontSize={10} fill={cLightGray} letterSpacing={1}>
          {/* Top Right */}
          <text x={1500} y={150}>REAL GDP GROWTH</text>
          <line x1={1500} x2={1650} y1={155} y2={155} stroke={cGray} strokeWidth={0.5} />
          
          {/* Center Left */}
          <text x={150} y={600} fill={cRed}>TERM PREMIUM</text>
          <circle cx={135} cy={597} r={2} fill={cRed} />

          {/* Bottom Right */}
          <text x={1600} y={650}>YIELD CURVE</text>
          <path d="M 1600 660 Q 1700 700, 1800 680" fill="none" stroke={cGray} strokeWidth={1} />

          {/* Bottom Center */}
          <text x={900} y={850} fill={cChartreuse}>VOLATILITY REGIME</text>
          <path d="M 850 870 Q 950 820, 1050 870 T 1250 870" fill="none" stroke={cChartreuse} strokeWidth={1} opacity={0.5} />
          
          {/* Mid Left */}
          <text x={350} y={750}>INFLATION EXPECTATIONS</text>
          <line x1={350} x2={550} y1={755} y2={755} stroke={cGray} strokeWidth={0.5} />
        </g>

        {/* Bottom Data Ticker / Axis */}
        <g transform={`translate(0, ${height - 40})`} fontSize={10} letterSpacing={1}>
          <line x1={50} x2={width - 50} y1={0} y2={0} stroke={cGray} strokeWidth={0.5} opacity={0.5} />
          
          <text x={100} y={20} fill={cLightGray}>EQUITIES</text>
          <text x={100} y={35} fill={cChartreuse}>+0.27%</text>

          <text x={350} y={20} fill={cLightGray}>RATES</text>
          <text x={350} y={35} fill={cRed}>-0.11%</text>

          <text x={600} y={20} fill={cLightGray}>CREDIT</text>
          <text x={600} y={35} fill={cChartreuse}>+0.08%</text>

          <text x={850} y={20} fill={cLightGray}>COMMODITIES</text>
          <text x={850} y={35} fill={cChartreuse}>+0.19%</text>

          <text x={1100} y={20} fill={cLightGray}>FX</text>
          <text x={1100} y={35} fill={cRed}>-0.04%</text>

          <text x={1350} y={20} fill={cLightGray}>GROWTH</text>
          <text x={1350} y={35} fill={cChartreuse}>+0.16%</text>
        </g>

      </svg>

      {/* FILM GRAIN / TEXTURE OVERLAY */}
      <svg width="100%" height="100%" style={{ position: "absolute", pointerEvents: "none", zIndex: 0, opacity: 0.04, mixBlendMode: "overlay" }}>
        <filter id={grainFilterId}>
          <feTurbulence type="fractalNoise" baseFrequency="0.65" numOctaves="3" stitchTiles="stitch" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${grainFilterId})`} />
      </svg>

      {/* HERO TITLE (Resolves in negative space after pullback) */}
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          opacity: titleOpacity,
          filter: `blur(${titleBlur}px)`,
          zIndex: 10,
          pointerEvents: "none"
        }}
      >
        <div
          style={{
            fontSize: `${160 * (Math.min(width, height) / 1080)}px`,
            color: cIvory,
            letterSpacing: "0.08em",
            textShadow: "0px 4px 12px rgba(0,0,0,0.6), 0px 0px 2px rgba(242, 233, 216, 0.2)",
            textAlign: "center",
            lineHeight: 1,
            // Slight optical adjustment to center perfectly given the tracking
            transform: "translateX(0.04em)"
          }}
        >
          {title}
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default MacromoneyTitle;